# -*- coding: utf-8 -*-
import io
p = 'tmp/thesis_draft.md'
s = io.open(p, encoding='utf-8').read()

old_41 = "### 4.1 人在回路与人机协同\n\n> 【待补】本节讨论人为什么需要参与、Human-in-the-loop 基本逻辑、人工确认如何提高知识可靠性，及现有应用案例。引用：付雅明⑨、陈勇⑩、周辉⑪、吴诺曼⑫。"

new_41 = "### 4.1 人在回路与人机协同\n\n第三章的讨论已经表明，可信性的技术性保障并不能回答\u201c这一信息在何种条件、何种边界下可信\u201d的具体问题，而这恰恰是需要人的判断介入之处。\u201c人在回路\u201d（Human-in-the-loop）的基本逻辑正在于此：将人的权威性判断嵌入自动化流程的关键节点，以弥补机器在边界界定与可信性裁量上的不足。付雅明等以科学家档案知识服务平台为例，阐述了\u201c人在回路\u201d理念下可信知识服务的构建方式，指出人的参与能够在知识抽取、校验与组织的环节中发挥不可替代的确认作用，从而使知识服务的产出从\u201c可能正确\u201d走向\u201c经过确认\u201d[9]。\n\n人在回路的必要性，在垂直领域的高风险场景中尤为凸显。陈勇等基于关联方资金占用案例，研究了人机协同视角下大语言模型对审计定性质量的提升机制，发现模型虽能高效地完成信息归集与初步研判，但最终的定性判断仍需审计人员结合专业判断予以确认，人机协同的关键不在于让机器替代人，而在于为人的判断提供更充分、更可靠的依据[10]。这一结论指向一个更一般的原则：人的角色从\u201c执行者\u201d转向\u201c验证者\u201d与\u201c责任承担者\u201d。\n\n与此同时，对模型行为的治理与审计也在为\u201c人在回路\u201d提供制度性的支撑。周辉等从技术治理的角度，提出了以对抗测试与评估审计为核心的大语言模型安全治理框架，强调对模型输出的系统性审查是保障其可用性与可信性的前提[11]。而从应用落地看，吴诺曼等以图书编目为场景，展示了\u201c人在回路\u201d的生成式人工智能如何在实际业务中嵌入人工确认环节，使自动化产出在进入知识库之前接受人工校验[12]。\n\n综合这些研究可以发现，\u201c人在回路\u201d已被不同领域共同认可为可信知识服务与高风险决策中的必要环节：如果缺少人的验证，信息就难以从\u201c证据候选\u201d上升为\u201c被采信的证据\u201d。然而，现有研究大多在各自的具体场景中论及\u201c人的确认\u201d，尚未进一步追问：经过人工确认的证据，如何被系统地组织为可复用、可治理的知识？这正是 4.2 与 4.3 要厘清的问题。"

old_43 = "### 4.3 小结\n\n> 【待补】本节小结：Validation ≠ Knowledge Organization——\u201c人确认了\u201d并不自动意味着\u201c已形成可复用知识\u201d（为第五章铺路）。引用：赵浜⑬、高颖⑭、陈宋生⑮、王亮⑯。"

new_43 = "### 4.3 小结\n\n本章梳理了两条在现有研究中并行展开、却鲜少被打通的脉络：一条是以\u201c人在回路\u201d为核心的验证机制，另一条是以 RAG、知识图谱与知识服务为核心的知识组织机制。前者回答\u201c证据如何被确认\u201d，后者回答\u201c知识如何被组织\u201d。付雅明、陈勇、周辉等的工作表明，人的确认是信息可信化的关键一步；而高颖等基于\u201cLLMs+GraphRAG\u201d的语义知识组织[14]、陈宋生等面向财会领域的知识图谱构建[15]、王亮等对 RAG 驱动知识服务的系统梳理[16]，则展示了知识组织在工程上的成熟路径。\n\n然而，一个关键的区别在此显现：\u201c被确认的证据\u201d与\u201c被组织的知识\u201d并不等同。知识的组织解决的是信息的结构化呈现与检索问题，其前提是这些知识单元已经被认定为可信；而\u201c可信\u201d的认定，恰恰需要回到人工验证这一上游环节。换言之，验证（Validation）与知识组织（Knowledge Organization）是两个不同层次的问题，现有研究分别在两个层次上有所建树，却缺乏将二者统一起来的机制性思考。赵浜等关于生成式人工智能结合知识库与智能体开展知识挖掘的探析，已经触及\u201c知识在验证之后如何被进一步转化为可调用的能力\u201d这一更前沿的问题[13]，但其讨论仍处于设想层面。如何在一条连贯的链条中，让\u201c经验证的证据\u201d顺利转化为\u201c被组织的知识\u201d，进而沉淀为\u201c可复用的能力\u201d，正是下一章要进一步审视的问题。"

assert old_41 in s, "4.1 anchor not found"
s = s.replace(old_41, new_41)
assert old_43 in s, "4.3 anchor not found"
s = s.replace(old_43, new_43)

io.open(p, 'w', encoding='utf-8').write(s)
print("OK: 4.1 字数", len(new_41), "; 4.3 字数", len(new_43))
